import os
from shutil import copyfile, rmtree
import zipfile
from contextlib import contextmanager


def copy_file_to_new_location(current_path, new_location):
    """
    Save a file by copying it to a new location and removing the original.

    :param str current_path: Path to the file that should be copied and then removed.
    :param str new_location: Path where the file should be saved (copied to).
    """
    copyfile(current_path, new_location)
    os.remove(current_path)


def save_to_file(content, target_path):
    """
    Save the content of a text file to a new location.
    If content is bytes it is decoded before saving.

    :param Union[str, bytes] content: Content to be saved.
    :param str target_path: Path where the file should be saved.
    """
    if isinstance(content, bytes):
        content = content.decode(encoding='utf-8')

    with open(target_path, "w") as f:
        f.write(content)

def save_to_file_as_bytes(content, target_path):
    """
    Saves the content of a file to a target location.
    The content is treated as bytes and written directly.

    :param bytes content: Content to be saved.
    :param str target_path: Path where the file should be saved.
    """
    with open(target_path, "wb") as f:
        f.write(content)

@contextmanager
def unzip_file_with_cleanup(file_path):
    """
    Context manager that unzips a file and automatically cleans up the extracted content.

    Usage:
        with unzip_file_with_cleanup('/path/to/file.zip') as extracted_path:
            # Use the extracted files
            do_something(extracted_path)
        # Files are automatically cleaned up here

    :param str file_path: Path to the zip file.
    :yield: path to the unzipped content
    :rtype: str
    """
    extracted_path = None
    try:
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall(file_path.replace(".zip", ""))

        extracted_path = file_path.replace(".zip", "")
        yield extracted_path
    finally:
        if extracted_path and os.path.exists(extracted_path):
            if os.path.isdir(extracted_path):
                rmtree(extracted_path)
            else:
                os.remove(extracted_path)
